const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',bug:'M8 9h8v9a4 4 0 0 1-8 0zM9 5l2 4m4-4-2 4M4 10h4m8 0h4M3 15h5m8 0h5M4 21l4-3m8 0 4 3',change:'M3 7h16m-4-4 4 4-4 4M21 17H5m4-4-4 4 4 4',task:'M9 6h11M9 12h11M9 18h11M3 6l1 1 2-2M3 12l1 1 2-2M3 18l1 1 2-2',graph:'M4 3h5v5H4zM15 16h5v5h-5zM4 16h5v5H4zM6.5 8v8m0-4h11v4',check:'m4 12 5 5L20 6',code:'m8 6-6 6 6 6m8-12 6 6-6 6m-3-14-2 16',inbox:'M4 4h16v16H4zM4 14h5l2 3h2l2-3h5',agent:'M6 7h12v13H6zM12 3v4M9 12h.01M15 12h.01M9 16h6M3 10v6m18-6v6',asset:'M3 6h7l2 2h9v12H3z',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',chart:'M3 3v18h18M7 17v-5m5 5V7m5 10V4',book:'M4 3h16v18H4zM8 7h8M8 11h8M8 15h5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',moon:'M21 13a9 9 0 0 1-10-10 9 9 0 1 0 10 10',close:'m6 6 12 12M6 18 18 6',menu:'M3 6h18M3 12h18M3 18h18',chevron:'m9 5 7 7-7 7',up:'m6 14 6-6 6 6',plus:'M12 4v16M4 12h16',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',arrow:'M4 12h16m-6-6 6 6-6 6',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',file:'M5 3h9l5 5v13H5zM14 3v5h5M9 13h6M9 17h6',filter:'M3 4h18l-7 8v7l-4 2V12z'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.info}"/></svg>`;
const routes={overview:['项目概览','grid','工作空间'],inbox:['我的工作台','inbox','工作空间'],requirements:['需求池','list','产品管理'],defects:['缺陷池','bug','产品管理'],changes:['需求变更','change','产品管理'],tasks:['任务与验收','task','工程交付'],planning:['规划与依赖','graph','工程交付'],quality:['测试与质量','check','工程交付'],code:['代码与交付','code','工程交付'],agents:['Agent 协作','agent','协作与资源'],assets:['项目资产','asset','协作与资源'],context:['资料与里程碑','info','协作与资源'],time:['时间与效率','chart','分析与设置'],retrospective:['项目复盘','book','分析与设置'],settings:['项目设置','settings','分析与设置']};
const storageKey='project-board-product-prototype-v1';let memoryOnly=false,toastTimer,lastFocus=null,formHandler=null,drawerKind=null,drawerId=null,drawerTab='概述';
const blankProject=()=>({requirements:[],defects:[],tasks:[],changes:[],usage:[],unknownSessions:0,retrospect:[]});
const fresh=()=>({schema:1,project:'board',role:'human',theme:'light',dense:false,projects:{board:structuredClone(demoSeed),sample:blankProject()},filters:{},savedViews:[]});
let state;
try{const raw=localStorage.getItem(storageKey);state=raw?JSON.parse(raw):fresh();if(state.schema!==1||!state.projects?.board)state=fresh();}catch{state=fresh();memoryOnly=true;}
let route=location.hash.slice(1).split('/')[0]||'requirements';if(!routes[route])route='requirements';let selected=new Set();
const data=()=>state.projects[state.project];const manager=()=>state.role!=='worker';
const persist=()=>{try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{memoryOnly=true;}if($('storage-status'))$('storage-status').textContent=memoryOnly?'浏览器禁止存储 · 本次会话内有效':'仅本浏览器保存';};
const notify=message=>{$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500);};
const btn=(label,action,attrs='',style='')=>`<button class="${style}" data-action="${action}" ${attrs}>${label}</button>`;
const badge=(value)=>{const cls=['已达成','已关闭','已验收','已吸收','已批准','完整'].includes(value)?'good':['P0','S1 · 严重','重开'].includes(value)?'bad':['待评估','待澄清','待分诊','待复测','待影响确认','部分'].includes(value)?'warn':['执行中','进行中','修复中','已确认','已承诺','待验收','待评审'].includes(value)?'info':'';return `<span class="status ${cls}">${esc(value)}</span>`;};
const priority=value=>`<span class="priority ${value==='P0'?'critical':value==='P1'?'high':''}">${icon(value==='P2'?'chevron':'up')}${esc(value)}</span>`;
const number=value=>value===null||value===undefined?'—':new Intl.NumberFormat('zh-CN').format(value);
const short=value=>value>=1000000?(value/1000000).toFixed(2)+'M':value>=1000?(value/1000).toFixed(1)+'K':number(value);
const f=()=>state.filters[state.project+':'+route]??=({query:'',status:'全部',priority:'全部',type:'全部',view:'全部',page:1,sort:'updated',dir:-1,mode:'list',dimension:'phase',range:'7',runtime:'全部',source:'全部'});
function openRoute(next){closeDrawer(false);route=routes[next]?next:'requirements';selected.clear();location.hash=route;render();window.scrollTo(0,0);closeNav();}
function header(title,description,primary='',actions=''){return `<div class="page-header"><div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="header-actions">${actions}${primary}</div></div>`;}
function empty(title,description,action=''){return `<div class="empty-state"><span class="empty-symbol">${icon('inbox')}</span><h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`;}
const select=(id,label,values,value)=>`<label><span class="sr-only">${esc(label)}</span><select id="${id}" aria-label="${esc(label)}">${values.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
function render(){
 if(state.role!=='human'&&state.project!=='board')state.project='board';document.documentElement.dataset.theme=state.theme;document.body.classList.toggle('dense',state.dense);$('theme-toggle').innerHTML=icon(state.theme==='light'?'moon':'sun');$('theme-toggle').setAttribute('aria-label',state.theme==='light'?'切换到深色主题':'切换到浅色主题');$('menu-toggle').innerHTML=icon('menu');$('modal-close').innerHTML=icon('close');$('role').value=state.role;$('project').value=state.project;$('project').querySelector('[value="sample"]').disabled=state.role!=='human';document.querySelector('.project-symbol').textContent=state.project==='board'?'PB':'BT';document.querySelector('.avatar').textContent=state.role==='human'?'人':state.role==='se'?'SE':'W';
 $('breadcrumbs').innerHTML=`<span>${esc(state.project==='board'?'项目公告板':'示例项目 Beta')}</span><span>/</span><span>${routes[route][2]}</span><span>/</span><span>${routes[route][0]}</span>`;
 let last='';$('nav').innerHTML=Object.entries(routes).map(([key,[label,name,group]])=>{const start=last!==group?`${last?'</div>':''}<div class="nav-group"><p>${group}</p>`:'';last=group;const count=key==='requirements'?data().requirements.filter(r=>['想法','待评估','待澄清'].includes(r.status)).length:key==='defects'?data().defects.filter(r=>r.status==='待分诊').length:0;return start+`<button class="nav-item" data-action="route" data-route="${key}" ${key===route?'aria-current="page"':''}>${icon(name)}<span>${label}</span>${count?`<span class="nav-count">${count}</span>`:''}</button>`;}).join('')+'</div>';
 const views={requirements:renderRequirements,defects:renderDefects,changes:renderChanges,tasks:renderTasks,time:renderTime,overview:renderOverview,inbox:renderInbox,planning:renderPlanning,quality:renderQuality,code:renderCode,agents:renderAgents,assets:renderAssets,context:renderContext,retrospective:renderRetrospective,settings:renderSettings};if(state.project==='sample'&&['planning','quality','code','agents','assets','context'].includes(route))$('page').innerHTML=header(routes[route][0],'只展示当前项目的记录。')+empty('当前项目尚未登记这些内容','另一个项目的数据、权限与材料不会自动复制到这里。');else views[route]();persist();
}
function requestRows(){const a=f();let rows=data().requirements.filter(r=>(a.view==='全部'||(a.view==='想法池'?r.status==='想法':a.view==='待澄清'?['待评估','待澄清'].includes(r.status):a.view==='已承诺'?['已承诺','执行中','待验收'].includes(r.status):r.status==='已达成'))&&(a.status==='全部'||r.status===a.status)&&(a.priority==='全部'||r.priority===a.priority)&&(a.type==='全部'||r.type===a.type)&&[r.id,r.title,r.owner,...r.tags].join(' ').toLowerCase().includes(a.query.toLowerCase()));const key=a.sort;return rows.sort((x,y)=>String(x[key]||'').localeCompare(String(y[key]||''),'zh-CN')*a.dir);}
function renderRequirements(){
 const a=f(),all=data().requirements,rows=requestRows();a.page=Math.min(a.page,Math.max(1,Math.ceil(rows.length/8)));const tabs=['全部','待澄清','已承诺','想法池','已达成'];
 $('page').innerHTML=header('需求池','记录现在要解决的问题，也保留未来值得探索的想法。',btn(icon('plus')+' 记录需求','create-requirement','','primary'),btn('已保存的视图','saved-views','','secondary-action'))+
 `<div class="view-tabs" role="tablist" aria-label="需求视图">${tabs.map(v=>`<button role="tab" aria-selected="${a.view===v}" data-action="req-view" data-value="${v}">${v}<span>${v==='全部'?all.length:v==='待澄清'?all.filter(r=>['待评估','待澄清'].includes(r.status)).length:v==='想法池'?all.filter(r=>r.status==='想法').length:v==='已达成'?all.filter(r=>r.status==='已达成').length:all.filter(r=>['已承诺','执行中','待验收'].includes(r.status)).length}</span></button>`).join('')}</div>`+
 `<div class="toolbar"><input id="list-query" type="search" aria-label="搜索需求" placeholder="搜索标题、编号、负责人或标签" value="${esc(a.query)}">${select('list-status','需求状态',['全部','想法','待评估','待澄清','已确认','已承诺','执行中','待验收','已达成','暂缓','不采纳'],a.status)}${select('list-priority','需求优先级',['全部','P0','P1','P2'],a.priority)}${select('list-type','需求来源类型',['全部','核心需求','过程扩展','未来想法'],a.type)}<div class="toolbar-end">${btn(a.mode==='list'?'看板视图':'列表视图','toggle-view')}${btn('列与密度','columns')}</div></div><div class="filter-note"><span>${rows.length} 项需求</span><span>·</span><span>优先级与交付承诺分别管理</span>${btn('清除筛选','clear-filters','','link-button')}</div><div id="requirement-results"></div>`;
 const host=$('requirement-results');
 if(!rows.length){host.innerHTML=empty(all.length?'没有匹配的需求':'这个项目还没有需求',all.length?'调整筛选或搜索词，已登记的数据没有被删除。':'先记录一个问题或想法，不需要先拆任务或填写工程验收。',btn(all.length?'清除筛选':'记录第一个想法',all.length?'clear-filters':'create-requirement','','primary'));wireFilters();return;}
 let content;
 if(a.mode==='board')content=`<div class="view-board">${[['未承诺',['想法','待评估','待澄清']],['已承诺',['已承诺']],['交付中',['执行中','待验收']],['已达成 / 已处置',['已达成','暂缓','不采纳']]].map(([title,states])=>`<section class="board-column"><h3>${title} · ${rows.filter(r=>states.includes(r.status)).length}</h3>${rows.filter(r=>states.includes(r.status)).map(r=>`<button class="board-card" data-action="open" data-kind="requirement" data-id="${r.id}"><span class="small muted">${r.id}</span>${esc(r.title)}<span class="small">${badge(r.status)} ${priority(r.priority)}</span><span class="small muted">${esc(r.owner)} · ${r.tasks.length} 个任务</span></button>`).join('')}</section>`).join('')}</div>`;
 else content=`<div class="table-wrap"><table aria-label="项目需求列表"><thead><tr><th><input type="checkbox" id="select-visible" aria-label="选择本页需求"></th><th>${btn('需求 / 标题','sort','data-key="title"')}</th><th>状态</th><th>${btn('优先级','sort','data-key="priority"')}</th><th class="hide-medium">类型 / 来源</th><th class="hide-mobile">负责人</th><th>任务</th><th class="hide-medium">${btn('最近更新 ↓','sort','data-key="updated"')}</th></tr></thead><tbody>${rows.slice((a.page-1)*8,a.page*8).map(r=>`<tr><td><input type="checkbox" aria-label="选择 ${r.id}" data-check="${r.id}" ${selected.has(r.id)?'checked':''}></td><td class="title-cell"><span class="key">${r.id}${r.version?' · v'+r.version:' · 未定版'}</span><button class="item-title" data-action="open" data-kind="requirement" data-id="${r.id}">${esc(r.title)}</button></td><td>${badge(r.status)}</td><td>${priority(r.priority)}</td><td class="compact hide-medium">${esc(r.type)}<br><span class="muted">${esc(r.origin)}</span></td><td class="compact hide-mobile nowrap">${esc(r.owner)}</td><td>${btn(String(r.tasks.length),'open',`data-kind="requirement" data-tab="关联交付" data-id="${r.id}"`,'link-button')}</td><td class="small muted hide-medium nowrap">${r.updated.slice(5)}</td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>第 ${(a.page-1)*8+1}–${Math.min(a.page*8,rows.length)} 项，共 ${rows.length} 项</span><div class="inline-actions">${btn('上一页','page-prev',a.page===1?'disabled':'')}${btn('下一页','page-next',a.page*8>=rows.length?'disabled':'')}</div></div>`;
 host.innerHTML=`<div id="bulk-bar" class="bulk-bar" ${selected.size?'':'hidden'}><strong id="bulk-count">已选 ${selected.size} 项</strong>${btn('设置标签','bulk-tag',manager()?'':'disabled')}${btn('取消选择','clear-selection')}</div>${content}`;wireFilters();
}
function wireFilters(){for(const [id,key] of [['list-query','query'],['list-status','status'],['list-priority','priority'],['list-type','type']]){const input=$(id);if(!input)continue;input.addEventListener(id==='list-query'?'input':'change',()=>{const caret=id==='list-query'?input.selectionStart:null;f()[key]=input.value;f().page=1;selected.clear();render();if(id==='list-query'){$(id).focus();$(id).setSelectionRange(caret,caret);}});}}
function renderDefects(){const a=f(),rows=data().defects.filter(r=>[r.id,r.title,r.environment].join(' ').toLowerCase().includes(a.query.toLowerCase())&&(a.status==='全部'||r.status===a.status)&&(a.priority==='全部'||r.priority===a.priority));$('page').innerHTML=header('缺陷池','从现象登记到目标版本复测；修复任务完成不等于缺陷已关闭。',btn(icon('plus')+' 报告缺陷','create-defect','','primary'))+`<div class="view-tabs" aria-label="缺陷范围"><button aria-selected="true">全部缺陷 <span>${data().defects.length}</span></button></div><div class="toolbar"><input type="search" id="list-query" aria-label="搜索缺陷" placeholder="搜索编号、现象或环境" value="${esc(a.query)}">${select('list-status','缺陷状态',['全部','待分诊','已确认','修复中','待复测','已关闭','重开'],a.status)}${select('list-priority','缺陷优先级',['全部','P0','P1','P2'],a.priority)}</div>`+(rows.length?`<div class="table-wrap"><table aria-label="项目缺陷列表"><thead><tr><th>缺陷 / 现象</th><th>状态</th><th>严重度</th><th>优先级</th><th class="hide-mobile">负责人</th><th>关联需求</th><th class="hide-medium">复测用例</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="title-cell"><span class="key">${r.id}</span><button class="item-title" data-action="open" data-kind="defect" data-id="${r.id}">${esc(r.title)}</button></td><td>${badge(r.status)}</td><td class="small nowrap">${esc(r.severity)}</td><td>${priority(r.priority)}</td><td class="small hide-mobile">${esc(r.owner)}</td><td>${r.requirement?btn(r.requirement,'open',`data-kind="requirement" data-id="${r.requirement}"`,'link-button'):'—'}</td><td class="small hide-medium">${esc(r.caseId)}</td></tr>`).join('')}</tbody></table></div><div class="filter-note section-gap">严重度判断影响，优先级决定处理顺序；两者不自动互相推导。</div>`:empty('没有匹配的缺陷','未知或暂未复现也可以先登记，后续逐步补充证据。',btn('报告缺陷','create-defect','','primary')));wireFilters();}
function renderChanges(){const rows=data().changes;$('page').innerHTML=header('需求变更','保留承诺版本，让每次调整都能看到原因、影响与确认结果。',manager()?btn('提出变更','choose-change','','primary'):'')+`<div class="notice">变更提案不会修改当前有效需求；批准后只重新核定实际受影响的任务、接口与验收。</div>`+(rows.length?`<div class="table-wrap section-gap"><table aria-label="需求变更列表"><thead><tr><th>变更提案</th><th>需求 / 目标版本</th><th>状态</th><th>影响任务</th><th>提出日期</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="title-cell"><span class="key">${r.id}</span><button class="item-title" data-action="open" data-kind="change" data-id="${r.id}">${esc(r.title)}</button></td><td>${btn(r.requirement,'open',`data-kind="requirement" data-id="${r.requirement}"`,'link-button')}<div class="small muted">拟定 v${r.version}</div></td><td>${badge(r.status)}</td><td>${r.impact.length} 项</td><td class="small muted">${r.at}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有需求变更','核心需求定版后，新想法可以继续记录；只有改变已承诺范围时才走变更。'));}
function renderTasks(){const a=f(),rows=data().tasks.filter(t=>[t.id,t.title,t.owner,...taskSourceIds(t)].join(' ').toLowerCase().includes(a.query.toLowerCase()));$('page').innerHTML=header('任务与验收','需求解释为什么做；任务明确谁在什么边界内交付。',btn('查看可领取任务','available-tasks','','primary'))+`<div class="toolbar"><input id="list-query" type="search" aria-label="搜索任务" placeholder="搜索任务、关联需求或执行者" value="${esc(a.query)}"></div>`+(rows.length?`<div class="table-wrap"><table aria-label="任务列表"><thead><tr><th>任务</th><th>状态</th><th>来源需求</th><th class="hide-mobile">执行者</th><th>基线状态</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="title-cell"><span class="key">${r.id}</span><button class="item-title" data-action="open" data-kind="task" data-id="${r.id}">${esc(r.title)}</button></td><td>${badge(r.status)}</td><td>${taskSourceIds(r).map(id=>btn(id,'open',`data-kind="requirement" data-id="${id}" data-tab="关联交付"`,'link-button')).join('<br>')}</td><td class="small hide-mobile">${r.owner}</td><td>${badge(r.baseline)}</td></tr>`).join('')}</tbody></table></div>`:empty('没有匹配的任务','先澄清当前要实现的需求，再建立有独立交付边界的任务。'));wireFilters();}
function renderOverview(){const d=data(),openDefects=d.defects.filter(b=>b.status!=='已关闭');$('page').innerHTML=header('项目概览','从产品目标、当前交付和风险进入工作。',btn('查看待决策','route','data-route="inbox"','primary'))+`<div class="metric-grid">${metric('当前承诺需求',d.requirements.filter(r=>['已承诺','执行中','待验收'].includes(r.status)).length,'想法不计入本轮承诺','requirements')}${metric('待处理缺陷',openDefects.length,'修复与复测分别追踪','defects')}${metric('待评审任务',d.tasks.filter(t=>t.status==='待评审').length,'候选尚未进入基线','tasks')}${metric('已知 Token 用量',short(d.usage.reduce((s,r)=>s+r.input+r.output,0)),'覆盖范围见时间与效率','time')}</div><div class="grid-two"><section class="panel"><div class="panel-header"><h3>本轮里程碑</h3>${badge('进行中')}</div><h4>M2 · 产品治理</h4><p class="prose section-gap">将想法、承诺、任务、缺陷与验证串联，让复盘能回答范围为什么改变、投入花在哪里。</p><div class="stack-list">${[['产品模型','需求与缺陷生命周期已明确','requirements'],['交付验证','部分候选待复核；不把提交视为完成','tasks'],['投入统计','显示已知用量和未采集会话','time']].map(([t,b,r])=>`<div class="stack-row"><div>${btn(t,'route',`data-route="${r}"`,'link-button')}<p>${b}</p></div>${icon('chevron')}</div>`).join('')}</div></section><section class="panel"><div class="panel-header"><h3>需要关注</h3>${btn('全部待办','route','data-route="inbox"','link-button')}</div><div class="stack-list"><div class="stack-row"><div>${btn('用量结算变更尚未批准','open','data-kind="change" data-id="PB-CHG-006"','link-button')}<p>2 个任务可能受影响；原需求 v1 继续生效。</p></div>${badge('待确认')}</div><div class="stack-row"><div>${btn('窄屏问题等待复测','open','data-kind="defect" data-id="PB-BUG-017"','link-button')}<p>需在 demo-fix-01 核对 UI-08。</p></div>${badge('待复测')}</div><div class="stack-row"><div>${btn('需求池中还有未工程化想法','route','data-route="requirements"','link-button')}<p>保留未来方向，不自动变为执行任务。</p></div></div></div></section></div>`;if(state.project==='sample')$('page').innerHTML=header('项目概览','这是隔离的空白演示项目。')+empty('从一个真实目标开始','当前项目没有需求、任务或历史验收；上一项目的数据不会带入。',btn('记录第一个想法','create-requirement','','primary'));}
function metric(name,value,note,target){return `<button class="metric" data-action="route" data-route="${target}"><span class="metric-name">${esc(name)}</span><strong>${esc(value)}</strong><span class="small">${esc(note)}</span></button>`;}
function renderInbox(){const d=data();$('page').innerHTML=header(state.role==='worker'?'我的执行工作台':'我的决策工作台',state.role==='worker'?'自行领取、留言和交付；等待回复由当前任务约束决定。':'集中处理范围、交付与例外；普通任务保持最短路径。',btn(state.role==='worker'?'查看可领取任务':'查看交付队列','route','data-route="tasks"','primary'))+`<div class="grid-two"><section class="panel"><div class="panel-header"><h3>${state.role==='worker'?'当前可做':'产品待决策'}</h3></div>${state.role==='worker'?d.tasks.filter(t=>t.status==='待领取').map(t=>`<div class="stack-row"><div>${btn(t.title,'open',`data-kind="task" data-id="${t.id}"`,'link-button')}<p>${t.id} · ${t.requirement} · 无当前硬依赖阻塞</p></div></div>`).join(''):d.requirements.filter(r=>['待评估','待澄清'].includes(r.status)).map(r=>`<div class="stack-row"><div>${btn(r.title,'open',`data-kind="requirement" data-id="${r.id}"`,'link-button')}<p>${r.id} · 目标与范围尚未进入承诺</p></div>${badge(r.status)}</div>`).join('')}</section><section class="panel"><div class="panel-header"><h3>协作与验证</h3></div>${d.defects.filter(r=>r.status==='待复测').map(r=>`<div class="stack-row"><div>${btn(r.title,'open',`data-kind="defect" data-id="${r.id}"`,'link-button')}<p>${r.id} · 先核对修复版本，再复测</p></div>${badge(r.status)}</div>`).join('')}<div class="stack-row"><div>${btn('打开 Agent 协作','route','data-route="agents"','link-button')}<p>评论等待、原会话接续与有界复核授权保持现有语义。</p></div></div></section></div>`;}
function usageRows(){const a=f();return data().usage.filter(r=>(a.runtime==='全部'||r.runtime===a.runtime)&&(a.source==='全部'||r.quality===a.source)&&(a.range!=='today'||r.date==='2026-11-16'));}
function renderTime(){const a=f(),rows=usageRows(),total=rows.reduce((s,r)=>s+r.input+r.output,0),input=rows.reduce((s,r)=>s+r.input,0),output=rows.reduce((s,r)=>s+r.output,0),cache=rows.reduce((s,r)=>s+r.cache,0),sessions=rows.reduce((s,r)=>s+r.sessions,0),unknown=a.runtime==='全部'||a.runtime==='DeepSeek Harness'?data().unknownSessions:0,full=rows.filter(r=>r.coverage==='完整').reduce((s,r)=>s+r.sessions,0),partial=sessions-full;
 const groups={};for(const r of rows){const key=a.dimension==='task'?(r.task|| (r.phase==='未归因'?'待归因':'项目级调研')):a.dimension==='model'?r.model:r.phase;groups[key]=(groups[key]||0)+r.input+r.output;}
 const unassigned=rows.filter(r=>r.phase==='未归因').reduce((s,r)=>s+r.input+r.output,0);
 $('page').innerHTML=header('时间与效率','一起看投入、等待与模型用量；每个数字都说明统计范围。',btn('导出当前视图','export-usage','','primary'))+`<div class="view-tabs" role="tablist" aria-label="效率统计范围"><button role="tab" aria-selected="${a.view!=='时间'}" data-action="time-view" data-value="Token">Token 用量</button><button role="tab" aria-selected="${a.view==='时间'}" data-action="time-view" data-value="时间">时间与流动</button><button role="tab" aria-selected="${a.view==='复盘'}" data-action="route" data-route="retrospective">优化与复盘</button></div>`;
 if(a.view==='时间'){$('page').innerHTML+=`<div class="notice">以下为演示样本。投入工时、排队等待与项目历时分开统计；并行任务历时不能直接相加。</div><div class="metric-grid">${metric('已登记投入','42.5h','不等于领取到验收的历时','time')}${metric('等待与排队','12.0h','其中评审等待 6.5h','time')}${metric('返工投入','7.0h','属于投入，不重复加总','time')}${metric('记录完整任务','8 / 12','只对同类完整样本比较','time')}</div><div class="grid-two"><section class="panel"><div class="panel-header"><h3>可压缩环节</h3></div>${bars({'评审排队':6.5,'等待输入':3.5,'环境准备':2},12,'小时')}</section><section class="panel"><div class="panel-header"><h3>复盘问题</h3></div><p class="prose">先判断需求是否反复、材料是否缺失、评审是否排队，再判断是否能通过并行或工具压缩。Token 用量与工时只提供线索，不直接评价 Agent 表现。</p>${btn('查看项目复盘','route','data-route="retrospective"','link-button')}</section></div>`;return;}
 $('page').innerHTML+=`<div class="toolbar">${select('usage-range','统计周期',['最近 7 天','今天'],a.range==='today'?'今天':'最近 7 天')}${select('usage-runtime','运行时',['全部','Codex','Zcode','DeepSeek Harness'],a.runtime)}${select('usage-source','用量数据来源',['全部','实测','导入 · 已核对'],a.source)}<div class="toolbar-end">${btn('统计口径与采集范围','coverage')}</div></div><div class="notice ${unknown?'warning':''}">已关联会话中，${sessions} / ${sessions+unknown} 个有用量记录；${partial} 个仅部分采集，${unknown} 个未接入。项目外未登记会话不在分母内。${total?'当前合计是已知用量下限。':'缺失数据不等于 0 Token。'}</div><div class="metric-grid"><div class="metric"><span class="metric-name">已知 Token 合计</span><strong>${total?short(total):'—'}</strong><span class="small">输入 + 输出，含已知重试</span></div><div class="metric"><span class="metric-name">有记录的已关联会话</span><strong>${sessions} / ${sessions+unknown}</strong><span class="small">完整 ${full} · 部分 ${partial} · 未接入 ${unknown}</span></div><div class="metric"><span class="metric-name">缓存读取占输入</span><strong>${input?(cache/input*100).toFixed(1)+'%':'—'}</strong><span class="small">缓存已含在输入内，不另加</span></div><div class="metric"><span class="metric-name">待归因 Token</span><strong>${unassigned?short(unassigned):total?'0':'—'}</strong><span class="small">已计入项目合计，不平均摊给任务</span></div></div>`;
 if(!rows.length){$('page').innerHTML+=empty(unknown?'该运行时尚未接入用量采集':'当前筛选没有用量记录',unknown?'会话已登记，但没有可核验的用量样本。接入或按审核流程导入后才能统计。':'选择其他来源或周期，不把没有记录解读为没有消耗。',btn('查看采集范围','coverage'));wireUsage();return;}
 $('page').innerHTML+=`<div class="grid-two"><section class="panel"><div class="panel-header"><div><h3>已知用量趋势</h3><p>按发生日期，展示当前筛选的样本</p></div>${badge('演示数据')}</div>${trend(rows)}<div class="token-components"><span>输入 <strong>${short(input)}</strong></span><span>输出 <strong>${short(output)}</strong></span><span>缓存读取 <strong>${short(cache)}</strong><span class="muted">（输入子集）</span></span></div></section><section class="panel"><div class="panel-header"><h3>用量去向</h3>${select('usage-dimension','分组维度',['阶段','模型','任务'],a.dimension==='model'?'模型':a.dimension==='task'?'任务':'阶段')}</div>${bars(groups,total)}<p class="small muted">点击分组可查看明细；需求总量按唯一调用并集归集，避免多任务重复记账。</p></section></div><div class="section-gap"><div class="panel-header"><div><h3>用量明细</h3><p>原始记录只保留受控引用；此处不显示提示词、密钥或原始会话。</p></div>${btn('查看字段说明','coverage','','link-button')}</div><div class="table-wrap"><table aria-label="Token 用量明细"><thead><tr><th>发生日期 / 会话</th><th>模型 / 来源</th><th>归属任务 / 阶段</th><th>输入</th><th>输出</th><th>合计</th><th>覆盖</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="small nowrap">${r.date.slice(5)}<br><span class="muted">${manager()?r.session:'已脱敏会话'}</span></td><td class="small">${r.model}<br><span class="muted">${r.quality}</span></td><td>${r.task?btn(r.task,'open',`data-kind="task" data-id="${r.task}"`,'link-button'):`<span class="small">${r.phase==='未归因'?'待归因':'项目级调研'}</span>`}<div class="small muted">${r.phase}</div></td><td class="numeric small">${number(r.input)}</td><td class="numeric small">${number(r.output)}</td><td class="numeric small">${number(r.input+r.output)}</td><td>${badge(r.coverage)}</td></tr>`).join('')}</tbody></table></div><p class="small muted section-gap">Token 不等于实际费用或订阅额度。推理输出为输出子集；当前部分来源未报告推理细分，不能据此判断为 0。</p></div>`;wireUsage();
}
function wireUsage(){for(const [id,key,map] of [['usage-range','range',v=>v==='今天'?'today':'7'],['usage-runtime','runtime',v=>v],['usage-source','source',v=>v],['usage-dimension','dimension',v=>v==='模型'?'model':v==='任务'?'task':'phase']]){const node=$(id);if(node)node.onchange=()=>{f()[key]=map(node.value);render();};}}
function bars(groups,total,unit='Token'){return Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([label,value])=>`<div class="bar-row"><button class="bar-label" data-action="usage-group" data-value="${esc(label)}">${esc(label)}</button><div class="bar-track"><div class="bar-fill" style="width:${total?Math.max(2,value/total*100):0}%"></div></div><span class="bar-value">${unit==='小时'?value+'h':short(value)}</span></div>`).join('');}
function trend(rows){const daily={};for(const r of rows)daily[r.date]=(daily[r.date]||0)+r.input+r.output;const days=Object.keys(daily).sort(),max=Math.max(...Object.values(daily)),points=days.map((d,i)=>[40+(days.length===1?220:i/(days.length-1)*400),140-daily[d]/max*112]);return `<svg class="chart" viewBox="0 0 480 180" role="img" aria-label="每日用量：${esc(days.map(d=>d+' '+number(daily[d])+' Token').join('；'))}"><line x1="40" x2="440" y1="140" y2="140"/><line x1="40" x2="440" y1="84" y2="84"/><text x="4" y="32">${short(max)}</text><text x="18" y="144">0</text><path class="trend-area" d="M${points.map(p=>p.join(',')).join(' L')} L${points.at(-1)[0]},140 L${points[0][0]},140 Z"/><polyline class="trend-line" points="${points.map(p=>p.join(',')).join(' ')}"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="currentColor"/><text x="${x}" y="168" text-anchor="middle">${days[i].slice(5)}</text>`).join('')}</svg>`;}
function renderPlanning(){$('page').innerHTML=header('规划与依赖','先看业务目标，再看模块和任务；依赖与接口耦合分别展示。',btn('查看需求覆盖','route','data-route="requirements"','primary'))+`<div class="grid-two"><section class="panel"><h3>当前里程碑 M2</h3><div class="stack-list">${[['用量度量','PB-REQ-024','PB-T-101 → PB-T-102'],['产品治理','PB-REQ-025','先补目标与验收，不要求一次规划全部未来'],['交付质量','PB-REQ-027','修复任务与缺陷复测分别判断']].map(([t,id,desc])=>`<div class="stack-row"><div><h4>${t}</h4>${btn(id,'open',`data-kind="requirement" data-id="${id}"`,'link-button')}<p>${desc}</p></div></div>`).join('')}</div></section><section class="panel"><h3>依赖关系</h3><div class="trace-flow"><div class="trace-node">PB-T-101<strong>调用归集</strong>${badge('已吸收')}</div>${icon('arrow')}<div class="trace-node">PB-T-102<strong>用量展示</strong>${badge('进行中')}</div></div><p class="prose">下游基线消费已吸收的代码版本；需求来源关系不会变成硬依赖。共享接口变更继续由原冻结与影响确认机制处理。</p><div class="section-gap">${btn('查看接口与治理映射','design-section','data-section="migration"','link-button')}</div></section></div>`;}
function renderQuality(){$('page').innerHTML=header('测试与质量','按当前目标版本核对标准、运行结果和缺陷复测。',btn('查看待复测缺陷','route','data-route="defects"','primary'))+`<div class="table-wrap"><table aria-label="验证覆盖矩阵"><thead><tr><th>需求标准</th><th>验证用例</th><th>当前结果</th><th>关联缺陷</th></tr></thead><tbody><tr><td>${btn('PB-REQ-024 / AC-01','open','data-kind="requirement" data-id="PB-REQ-024" data-tab="关联交付"','link-button')}</td><td>T-21 · 去重与重放</td><td>${badge('已验收')}</td><td>${btn('PB-BUG-018','open','data-kind="defect" data-id="PB-BUG-018"','link-button')}</td></tr><tr><td>PB-REQ-024 / AC-02</td><td>T-22 · 缺失与覆盖</td><td>${badge('待评审')}</td><td>PB-BUG-019</td></tr><tr><td>PB-REQ-028 / AC-01</td><td>UI-08 · 窄屏操作</td><td>${badge('待复测')}</td><td>${btn('PB-BUG-017','open','data-kind="defect" data-id="PB-BUG-017"','link-button')}</td></tr></tbody></table></div><p class="prose section-gap">用例、自动运行、逐条评审保留现有能力。只在项目级缺陷池增加分诊与复测闭环，不复制一套相互漂移的测试记录。</p>`;}
function renderCode(){$('page').innerHTML=header('代码与交付','追踪实现、审核、合入与部署锚点，资料与运行记录继续留在本地或 NAS。',btn('查看交付任务','route','data-route="tasks"','primary'))+`<section class="panel"><h3>当前版本关系 · 演示</h3><div class="trace-flow"><div class="trace-node">实现<strong>demo-fix-01</strong>固定候选</div>${icon('arrow')}<div class="trace-node">测试<strong>同一输入</strong>独立复测</div>${icon('arrow')}<div class="trace-node">基线<strong>已核验后吸收</strong>原 Git 门禁</div></div><p class="prose">当前源码追踪页的提交、文件历史和溯源归入此入口。需求和缺陷关联稳定任务 ID，不把 Git 祖先关系当作旧测试可覆盖新修改的证明。</p></section>`;}
function renderAgents(){$('page').innerHTML=header('Agent 协作','机器与运行时、受管会话、问题通知和有界委派在同一处定位。',btn('查看协作待办','route','data-route="inbox"','primary'))+`<div class="grid-two"><section class="panel"><h3>受管会话 · 演示</h3><div class="stack-list"><div class="stack-row"><span class="avatar">SE</span><div><h4>Codex · GPT-6.1 Sol</h4><p>本项目 SE · 当前范围确认与交付复核</p></div>${badge('已连接')}</div><div class="stack-row"><span class="avatar">W</span><div><h4>Zcode · DeepSeek Flash</h4><p>Worker · PB-T-102 · 已采集部分用量</p></div>${badge('进行中')}</div><div class="stack-row"><div><h4>DeepSeek Harness</h4><p>未接入演示状态，不伪造可用模型或 Token 数值。</p></div>${badge('未接入')}</div></div></section><section class="panel"><h3>原协作规则继续生效</h3><ul class="compact-list secondary"><li>Worker 留言后可自主选择等待；SE 明确停止仍须遵守。</li><li>成果先进入候选队列，SE 或有界受托者复核。</li><li>本机权限与节点配对分开，不从远端下发任意命令。</li><li>用量缺失只产生数据质量提示，不阻塞普通交付。</li></ul>${btn('查看权限设计','design-section','data-section="permissions"','link-button')}</section></div>`;}
function renderAssets(){$('page').innerHTML=header('项目资产','统一登记本地与 NAS 原件入口，跨项目复用仍需明确审核。',btn('查看复盘产出','route','data-route="retrospective"','primary'))+`<div class="table-wrap"><table aria-label="资源目录设计示例"><thead><tr><th>资源</th><th>类别</th><th>存储边界</th><th>关联</th></tr></thead><tbody><tr><td>需求调研原始材料</td><td>调研</td><td>本地 / NAS，摘要与受控引用</td><td>需求来源</td></tr><tr><td>缺陷复现与测试记录</td><td>测试证据</td><td>本地 / NAS，固定版本与哈希</td><td>缺陷、用例、运行</td></tr><tr><td>用量采集原件</td><td>运行记录</td><td>原节点 / NAS，不上传会话全文</td><td>样本去重与审计</td></tr><tr><td>需求澄清与复盘检查清单</td><td>方法资产</td><td>审核发布的不可变版本</td><td>其他项目显式固定版本消费</td></tr></tbody></table></div><p class="prose section-gap">目录登记不会自动授予文件读取权限；缓存、美术源件、原始调研、日志与运行状态不进入源码 Git。</p>`;}
function renderContext(){$('page').innerHTML=header('资料与里程碑','保留背景、目标、材料、阶段达成路径和验收手段。',btn('查看设计说明','design-section','data-section="ia"','primary'))+`<div class="grid-two"><section class="panel"><h3>项目定义 · 演示</h3><dl class="details-grid section-gap"><div><dt>目标</dt><dd>让产品目标与工程交付可追溯</dd></div><div><dt>阶段</dt><dd>M2 · 产品治理</dd></div><div><dt>当前边界</dt><dd>需求、缺陷、Token、操作体验</dd></div><div><dt>未承诺方向</dt><dd>费用结算与公司经营治理</dd></div></dl></section><section class="panel"><h3>阶段路径</h3><ol class="compact-list secondary"><li>理解核心需求与未决问题</li><li>明确模块、接口和任务边界</li><li>并行交付与逐项验证</li><li>核对业务目标并沉淀复盘</li></ol><p class="small muted">原项目资料、规划策略、接口与角色交接入口在详细设计中一一映射。</p></section></div>`;}
function renderRetrospective(){$('page').innerHTML=header('项目复盘','用范围变化、质量结果和投入分布解释项目，而不是只数完成任务。',btn('查看复盘模板','design-section','data-section="retrospective"','primary'))+`<div class="metric-grid">${metric('已承诺后新增','2 项','先分清新增与原需求细化','changes')}${metric('待分析变更','1 项','保留接受和不采纳理由','changes')}${metric('已关闭缺陷','1 / 5','按影响与复测范围分析','defects')}${metric('完整用量会话','13 / 23','其余部分或未知，不用于精确比较','time')}</div><div class="grid-two">${data().retrospect.map(r=>`<section class="panel"><div class="panel-header"><h3>${esc(r.title)}</h3></div><p class="small muted">${esc(r.category)} · 待验证假设</p><p class="prose section-gap">${esc(r.observation)}</p><h4 class="section-gap">下一次怎样改进</h4><p class="prose">${esc(r.action)}</p><div class="section-gap">${btn(r.target,'open',`data-kind="requirement" data-id="${r.target}"`,'link-button')}</div></section>`).join('')}</div><p class="prose section-gap">对外复用的是审核后的方法与适用条件；跨项目比较要区分规模、任务类型、模型、工具、复用程度与记录完整度。</p>`;}
function renderSettings(){$('page').innerHTML=header('项目设置','设置低频管理项；普通 Worker 不承担整套治理表单。',btn('查看权限与迁移设计','design-section','data-section="permissions"','primary'))+`<div class="grid-two"><section class="panel"><h3>权限与身份</h3><div class="stack-list"><div class="stack-row"><div><h4>人类所有者</h4><p>独立账号，全项目查看与实例接入管理。</p></div></div><div class="stack-row"><div><h4>项目 SE</h4><p>本项目需求承诺、范围变更与有界复核授权。</p></div></div><div class="stack-row"><div><h4>Worker</h4><p>记录发现、关联本人任务、留言与提交候选。</p></div></div></div></section><section class="panel"><h3>本轮不新增的审批</h3><ul class="compact-list secondary"><li>记录想法只需要标题和描述。</li><li>低影响修正可由 SE 批准的规则简化。</li><li>不为每次 Token 上报生成一张任务卡。</li><li>需求不会因字段全部填满而自动通过。</li></ul><p class="small muted">这里是交互设计说明；真实权限仍由服务端校验，原型的身份选择器只是展示。</p></section></div>`;}
function openDrawer(kind,id,tab='概述'){
 const mapping={requirement:'requirements',defect:'defects',task:'tasks',change:'changes'};const item=data()[mapping[kind]]?.find(r=>r.id===id);if(!item){notify('当前项目不存在此对象；未读取其他项目数据。');return;}
 if(!drawerId)lastFocus=document.activeElement;drawerKind=kind;drawerId=id;drawerTab=tab;$('drawer').hidden=false;$('drawer-backdrop').hidden=false;document.querySelector('.app-layout').inert=true;document.querySelector('.topbar').inert=true;document.querySelector('.prototype-banner').inert=true;document.body.style.overflow='hidden';
 const tabs=kind==='requirement'?['概述','关联交付','变更记录','讨论']:kind==='defect'?['概述','修复与复测','变更记录','讨论']:[];
 let body=kind==='requirement'?requirementDetail(item):kind==='defect'?defectDetail(item):kind==='task'?taskDetail(item):changeDetail(item);
 $('drawer').innerHTML=`<div class="drawer-header"><span>${esc(item.id)} · ${kind==='requirement'?'需求':kind==='defect'?'缺陷':kind==='task'?'任务':'变更提案'}</span><button class="icon-button" data-action="close-drawer" aria-label="关闭详情">${icon('close')}</button></div><div class="drawer-content"><div class="inline-actions">${badge(item.status)}${item.priority?priority(item.priority):''}${kind==='requirement'?`<span class="small muted">${item.version?'当前有效 v'+item.version:'尚未定版'}</span>`:''}</div><h2 id="drawer-title">${esc(item.title)}</h2>${tabs.length?`<div class="view-tabs" role="tablist" aria-label="详情分区">${tabs.map(t=>`<button role="tab" aria-selected="${tab===t}" data-action="drawer-tab" data-value="${t}">${t}</button>`).join('')}</div>`:''}${body}</div>${drawerFooter(kind,item)}`;
 history.replaceState(null,'','#'+route+'/'+kind+'/'+encodeURIComponent(id));$('drawer').focus();
}
function closeDrawer(focus=true){if(!$('drawer')||$('drawer').hidden)return;const old=lastFocus;$('drawer').hidden=true;$('drawer-backdrop').hidden=true;document.querySelector('.app-layout').inert=false;document.querySelector('.topbar').inert=false;document.querySelector('.prototype-banner').inert=false;document.body.style.overflow='';drawerKind=null;drawerId=null;history.replaceState(null,'','#'+route);if(focus)(old?.isConnected?old:$('main')).focus();}
function drawerFooter(kind,item){let left='',right='';if(kind==='requirement'){left=btn('讨论 / 补充','drawer-tab','data-value="讨论"');right=manager()?item.version?btn('提出变更','propose-change','','primary'):btn('完善并评估','refine','','primary'):'';}if(kind==='defect'){left=btn('查看关联任务','drawer-tab','data-value="修复与复测"');right=manager()&&item.status==='待复测'?btn('登记独立复测','retest','','primary'):manager()&&item.status==='已关闭'?btn('重新打开','reopen-defect') :'';}if(kind==='task'){left=btn('查看来源需求','open',`data-kind="requirement" data-id="${item.requirement}"`);right=btn('查看验证与交付规则','design-section','data-section="traceability"','primary');}if(kind==='change'){left=btn('查看原需求','open',`data-kind="requirement" data-id="${item.requirement}"`);right=manager()&&item.status==='待影响确认'?btn('核对并确认变更','review-change','','primary'):'';}return `<div class="drawer-footer"><div class="inline-actions">${left}</div><div class="inline-actions">${right}</div></div>`;}
function requirementDetail(r){if(drawerTab==='讨论')return discussion(r);if(drawerTab==='变更记录')return historyHtml(r)+data().changes.filter(c=>c.requirement===r.id).map(c=>`<div class="stack-row"><div>${btn(c.title,'open',`data-kind="change" data-id="${c.id}"`,'link-button')}<p>${c.id} · ${c.status} · 拟定 v${c.version}</p></div></div>`).join('');if(drawerTab==='关联交付')return `<section class="drawer-section"><div class="panel-header"><h3>目标与交付覆盖</h3>${manager()?btn('关联执行任务','link-task'):''}</div><p class="small muted">任务完成只是交付事实；全部标准核对通过后，负责人再确认需求目标。</p>${r.criteria.length?r.criteria.map(c=>`<div class="criterion"><div>${badge(c.passed?'已验证':'待验证')} <strong>${esc(c.id)}</strong></div><p>${esc(c.text)}</p><div class="small">${c.task?btn(c.task,'open',`data-kind="task" data-id="${c.task}"`,'link-button'):'待关联任务'} · ${esc(c.evidence)}</div></div>`).join(''):'<div class="notice warning section-gap">尚未定义验收标准；可以保留想法，但暂不确认进入交付承诺。</div>'}</section><section class="drawer-section"><h3>关联任务 · ${r.tasks.length}</h3>${r.tasks.map(id=>taskLink(id)).join('')||'<p class="small muted">尚未建立任务，当前不会进入 Worker 执行队列。</p>'}</section>${r.status==='待验收'?btn('确认业务目标达成','validate-requirement',manager()?'':'disabled','primary'):''}`;
 return `<section class="drawer-section"><dl class="details-grid"><div><dt>类型 / 提出阶段</dt><dd>${esc(r.type)} · ${esc(r.origin)}</dd></div><div><dt>负责人</dt><dd>${esc(r.owner)}</dd></div><div><dt>交付承诺</dt><dd>${esc(r.release)}</dd></div><div><dt>当前版本</dt><dd>${r.version?'v'+r.version+' · 历史版本不可覆盖':'未定版 · 可逐步补充'}</dd></div></dl></section><section class="drawer-section"><h3>希望解决什么</h3><p class="prose">${esc(r.goal)}</p></section><section class="drawer-section"><h3>需求与边界</h3><p class="prose">${esc(r.body)}</p></section><section class="drawer-section"><h3>标签与来源</h3>${r.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}<p class="small muted section-gap">来自用户输入；保留提出时间、背景和后续决定。所有原型内容均为演示。</p></section><div class="notice">${r.version?'本页展示有效版本。新想法不会直接覆盖该版本；通过变更提案计算影响。':'记录阶段不需要填完工程表单。准备承诺实现时，再完善目标、边界、验收和优先级。'}</div>`;}
function defectDetail(r){if(drawerTab==='讨论')return discussion(r);if(drawerTab==='变更记录')return historyHtml(r);if(drawerTab==='修复与复测')return `<section class="drawer-section"><h3>修复任务</h3>${r.tasks.map(taskLink).join('')||'<p class="small muted">尚未安排独立修复任务。</p>'}</section><section class="drawer-section"><h3>目标复测条件</h3><dl class="details-grid"><div><dt>修复版本</dt><dd>${esc(r.fixedVersion)}</dd></div><div><dt>复测用例</dt><dd>${esc(r.caseId)}</dd></div><div><dt>目标环境</dt><dd>${esc(r.environment)}</dd></div><div><dt>回归风险</dt><dd>${esc(r.regressionRisk)}</dd></div></dl></section><div class="notice warning">修复完成进入待复测。关闭需要当前修复版本、环境、用例结果和受控证据；复测失败保留记录并重开。</div>`;return `<dl class="details-grid drawer-section"><div><dt>严重度</dt><dd>${esc(r.severity)}</dd></div><div><dt>处理优先级</dt><dd>${priority(r.priority)}</dd></div><div><dt>负责人</dt><dd>${esc(r.owner)}</dd></div><div><dt>关联需求</dt><dd>${r.requirement?btn(r.requirement,'open',`data-kind="requirement" data-id="${r.requirement}"`,'link-button'):'尚未关联'}</dd></div></dl>${[['复现环境',r.environment],['复现步骤',r.steps],['预期结果',r.expected],['实际现象',r.actual]].map(([t,b])=>`<section class="drawer-section"><h3>${t}</h3><p class="prose" style="white-space:pre-wrap">${esc(b)}</p></section>`).join('')}`;}
function taskSourceIds(task){return [...new Set([task.requirement,...data().requirements.filter(r=>r.tasks.includes(task.id)).map(r=>r.id)])].filter(Boolean);}
function taskLink(id){const t=data().tasks.find(t=>t.id===id);return t?`<div class="stack-row"><div>${btn(t.id+' · '+t.title,'open',`data-kind="task" data-id="${t.id}"`,'link-button')}<p>${t.owner} · ${t.verification}</p></div>${badge(t.status)}</div>`:'';}
function taskDetail(t){return `<dl class="details-grid drawer-section"><div><dt>执行者</dt><dd>${t.owner}</dd></div><div><dt>基线状态</dt><dd>${badge(t.baseline)}</dd></div><div><dt>来源需求</dt><dd>${taskSourceIds(t).map(id=>btn(id,'open',`data-kind="requirement" data-tab="关联交付" data-id="${id}"`,'link-button')).join('<br>')}</dd></div><div><dt>验收标准</dt><dd>${t.criterion}</dd></div></dl><section class="drawer-section"><h3>当前验证</h3><p class="prose">${t.verification}</p></section><section class="drawer-section"><h3>依赖与范围</h3><p class="prose">${t.depends.length?'依赖 '+t.depends.join('、'):'当前无已登记硬依赖。'} · ${t.status==='草案'?'尚未发布，不能领取。':'执行时仍核对原规划、写路径、资源与冻结接口。'}</p></section><div class="notice">保留现有任务治理。普通 Worker 不需要先填写需求管理或 Token 表单，按原最短流程留言、交付和返修。</div>`;}
function changeDetail(c){return `<section class="drawer-section"><h3>为什么调整</h3><p class="prose">${esc(c.reason)}</p></section><div class="diff-grid"><div class="diff-box"><h4>当前有效版本</h4>${esc(c.before)}</div><div class="diff-box"><h4>拟议版本 v${c.version}</h4>${esc(c.after)}</div></div><section class="drawer-section"><h3>直接影响 · ${c.impact.length} 个任务</h3>${c.impact.map(taskLink).join('')||'<p class="small muted">尚未核定，不推断为零影响。</p>'}</section><section class="drawer-section"><h3>确认结果</h3><p class="prose">${esc(c.decision)}</p></section><div class="notice warning">确认前原版本保持有效。若任务当前在执行，应在真实实现中核定范围版本、通知执行者并使相关旧验收失效；不会一键重开所有历史任务。</div>`;}
function historyHtml(item){return `<h3>不可覆盖的变更与决定</h3><div class="trail">${item.history.length?item.history.slice().reverse().map(r=>`<div class="trail-entry"><strong>${esc(r.what)}</strong><p>${esc(r.who)} · ${esc(r.at)}</p><div class="trail-content">${esc(r.body)}</div></div>`).join(''):'<p class="small muted">尚无处置记录；这不代表已经审核。</p>'}</div>`;}
function discussion(item){return `<h3>讨论与补充</h3><p class="small muted">评论保留上下文，不等于批准需求、变更范围或关闭缺陷。</p>${(item.comments||[]).map(c=>`<article class="comment"><span class="small muted">${esc(c.who)} · ${esc(c.at)}</span><p>${esc(c.body)}</p></article>`).join('')||'<p class="small muted section-gap">还没有讨论。</p>'}<div class="form-field section-gap"><label for="comment-text">补充说明</label><textarea id="comment-text" placeholder="记录背景、疑问或新的证据入口"></textarea></div>${btn('发布评论','comment','','primary')}`;}
function modal(title,html,handler=null){$('modal-title').textContent=title;$('modal-body').innerHTML=handler?`<form id="prototype-form">${html}<p class="form-error" id="form-error" role="alert"></p><div class="form-footer"><button type="button" data-action="close-modal">取消</button><button class="primary" type="submit">保存到演示</button></div></form>`:html;formHandler=handler;if(!$('modal').open)$('modal').showModal();if(handler)$('prototype-form').onsubmit=e=>{e.preventDefault();try{const form=new FormData(e.target);handler(form);persist();$('modal').close();render();if(drawerId)openDrawer(drawerKind,drawerId,drawerTab);}catch(error){$('form-error').textContent=error.message;}};}
function field(name,label,value='',type='text',hint=''){return `<div class="form-field"><label for="field-${name}">${label}</label>${type==='textarea'?`<textarea id="field-${name}" name="${name}" required maxlength="4000">${esc(value)}</textarea>`:`<input id="field-${name}" name="${name}" type="${type}" required value="${esc(value)}" maxlength="200">`}${hint?`<p>${esc(hint)}</p>`:''}</div>`;}
function fieldSelect(name,label,values,value){return `<div class="form-field"><label for="field-${name}">${label}</label><select name="${name}" id="field-${name}">${values.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`;}
function eventRow(item,what,body){item.history.push({at:'11-16 · 原型操作',who:state.role==='human'?'人类所有者':state.role==='se'?'项目 SE':'Worker',what,body});item.updated='2026-11-16';}
function createRequirement(){modal('记录一个需求或想法',`<p class="small muted" style="margin-bottom:20px">先保存上下文，准备实现时再补工程细节。不会自动发布任务。</p>${field('title','标题','','text','用一句话描述希望改善什么。')}${field('body','想解决的问题 / 想法','','textarea') }<div class="form-row">${fieldSelect('type','类型',['未来想法','核心需求','过程扩展'],'未来想法')}${fieldSelect('origin','提出阶段',['项目启动','执行过程','项目复盘','结项后'],'执行过程')}</div>`,form=>{const title=form.get('title').trim(),body=form.get('body').trim();if(!title||!body)throw Error('请填写标题和要解决的问题。');const n=Math.max(35,...data().requirements.map(r=>Number(r.id.split('-').at(-1))))+1;data().requirements.unshift({id:'PB-REQ-'+String(n).padStart(3,'0'),title,body,goal:body,type:form.get('type'),origin:form.get('origin'),status:form.get('type')==='未来想法'?'想法':'待评估',priority:'P2',owner:'未分配',release:'未承诺',version:0,criteria:[],tasks:[],tags:['原型新建'],updated:'2026-11-16',history:[],comments:[]});f().view='全部';f().query='';f().status='全部';f().type='全部';f().page=1;notify('已记录为未工程化需求，未创建或派发生产任务。');});}
function refineRequirement(){if(!manager())return;const r=data().requirements.find(r=>r.id===drawerId);modal('完善并评估需求',`${field('goal','用户目标',r.goal,'textarea')}${field('boundary','范围与非目标',r.body,'textarea')}${field('acceptance','可验证的验收标准（每行一项）',r.criteria.map(c=>c.text).join('\n'),'textarea')}<div class="form-row">${fieldSelect('priority','优先级',['P0','P1','P2'],r.priority)}${fieldSelect('decision','本次决定',['继续澄清','确认 v1，暂不排期','暂缓','不采纳'],'确认 v1，暂不排期')}</div>${field('reason','决定依据','','textarea')}`,form=>{const criteria=form.get('acceptance').split('\n').map(s=>s.trim()).filter(Boolean);if(!criteria.length)throw Error('确认需求前需要至少一条可验证标准。');r.goal=form.get('goal').trim();r.body=form.get('boundary').trim();r.priority=form.get('priority');r.criteria=criteria.map((text,i)=>({id:'AC-'+String(i+1).padStart(2,'0'),text,passed:false,task:'',evidence:'待关联与验证'}));r.version=form.get('decision').startsWith('确认')?1:0;r.status=r.version?'已确认':form.get('decision')==='继续澄清'?'待澄清':form.get('decision');r.owner=state.role==='human'?'产品负责人':'项目 SE';r.release='待安排';eventRow(r,form.get('decision'),form.get('reason'));notify('评估决定已保留；确认不等于任务已拆分或目标已达成。');});}
function linkTask(){if(!manager())return;const r=data().requirements.find(r=>r.id===drawerId);if(!r.criteria.length){notify('当前需求没有验收标准，先完善并评估。');return;}modal('关联后续执行任务',`${fieldSelect('criterion','要覆盖的验收标准',r.criteria.map(c=>c.id+' · '+c.text),r.criteria[0].id+' · '+r.criteria[0].text)}${fieldSelect('task','已有任务',data().tasks.map(t=>t.id+' · '+t.title),data().tasks[0]?.id+' · '+data().tasks[0]?.title)}${field('reason','关联依据','','textarea')}`,form=>{const id=form.get('task')?.split(' · ')[0],task=data().tasks.find(t=>t.id===id);if(!task)throw Error('当前项目任务不存在。');const c=r.criteria.find(c=>c.id===form.get('criterion').split(' · ')[0]);if(c.task&&c.task!==id)throw Error('该标准已有交付任务；请先评估替换影响，避免静默覆盖。');if(!r.tasks.includes(id))r.tasks.push(id);c.task=id;c.passed=false;c.evidence='关联待核验；不继承其他需求的验收结论';eventRow(r,'关联任务 '+id,form.get('reason'));notify('已建立追踪关系，没有自动改变任务范围或通过验收。');});}
function proposeChange(id=drawerId){if(!manager())return;const r=data().requirements.find(r=>r.id===id);if(!r?.version){notify('该需求尚未定版，先完善目标和边界。');return;}modal('提出需求变更',`<div class="notice">当前有效 v${r.version} 保持不变，以下保存为提案。</div><div class="section-gap">${field('title','变更摘要',r.title)}${field('reason','为什么需要变更','','textarea')}${field('after','拟议的新范围',r.body,'textarea')}${field('impact','受影响任务（逗号分隔；未知请写“待调查”）',r.tasks.join(', '),'text','不能凭空认定无影响。')}</div>`,form=>{const ids=form.get('impact').split(/[,，]/).map(s=>s.trim()).filter(Boolean);if(!ids.length)throw Error('请说明影响范围或标记待调查。');if(ids.some(id=>id!=='待调查'&&!data().tasks.some(t=>t.id===id)))throw Error('影响任务必须属于当前项目。');const n=Math.max(6,...data().changes.map(c=>Number(c.id.split('-').at(-1))))+1;const c={id:'PB-CHG-'+String(n).padStart(3,'0'),requirement:r.id,title:form.get('title'),reason:form.get('reason'),before:r.body,after:form.get('after'),impact:ids.filter(i=>i!=='待调查'),unknownImpact:ids.includes('待调查'),status:'待影响确认',decision:'尚未批准；原 v'+r.version+' 继续有效。',version:r.version+1,at:'2026-11-16'};data().changes.unshift(c);eventRow(r,'提出 '+c.id,'未覆盖当前版本。'+c.reason);notify('已保存变更提案，原需求版本与执行边界保持。');});}
function reviewChange(){if(!manager())return;const c=data().changes.find(c=>c.id===drawerId),r=data().requirements.find(r=>r.id===c.requirement);modal('核对需求变更',`<div class="notice warning">这是原型中的产品决定演示，不能证明生产任务的范围、接口或测试已经更新。</div><div class="section-gap">${fieldSelect('decision','处理决定',['暂缓，原版本继续','不采纳','确认变更并等待工程核定'],'暂缓，原版本继续')}${field('reason','决定与影响核对依据','','textarea')}<label class="checkline"><input name="checked" type="checkbox">已核对目标、关联任务、接口、测试和通知范围</label></div>`,form=>{const decision=form.get('decision');if(decision.startsWith('确认')&&(c.unknownImpact||!form.get('checked')))throw Error('影响未查明或未完成核对，不能确认变更。');if(decision.startsWith('确认')){if(c.version!==r.version+1)throw Error('目标版本已变化；重新核对提案，不覆盖当前版本。');r.version=c.version;r.body=c.after;r.status=['待安排','未承诺'].includes(r.release)?'已确认':'已承诺';r.criteria.forEach(x=>{x.passed=false;x.evidence='范围变化，等待重新核定';});c.status='待工程核定';c.decision='产品范围已确认；受影响任务的工程版本与测试尚需核定。'+form.get('reason');eventRow(r,'确认 v'+r.version,c.decision);}else{c.status=decision.startsWith('暂缓')?'暂缓':'不采纳';c.decision=form.get('reason');}notify('决定已记录。未自动重开历史任务或宣称验证通过。');});}
function createDefect(){modal('报告一个缺陷',`${field('title','现象摘要')}${field('actual','实际现象','','textarea')}${field('expected','预期结果','','textarea')}<div class="form-row">${fieldSelect('severity','影响严重度',['待判断','S1 · 严重','S2 · 一般','S3 · 轻微'],'待判断')}${fieldSelect('priority','建议优先级',['P0','P1','P2'],'P2')}</div><details><summary>补充复现条件（可以稍后完善）</summary><div class="section-gap">${field('environment','环境 / 版本','待补充')}${field('steps','复现步骤','待调查','textarea')}</div></details>`,form=>{const n=Math.max(21,...data().defects.map(r=>Number(r.id.split('-').at(-1))))+1;data().defects.unshift({id:'PB-BUG-'+String(n).padStart(3,'0'),title:form.get('title').trim(),actual:form.get('actual').trim(),expected:form.get('expected').trim(),environment:form.get('environment')||'待补充',steps:form.get('steps')||'待调查',severity:form.get('severity'),priority:form.get('priority'),status:'待分诊',owner:'未分配',requirement:'',tasks:[],caseId:'待补充',fixedVersion:'待固定',regressionRisk:'未知',history:[],comments:[]});f().query='';f().status='全部';notify('缺陷已进入待分诊，未自动创建修复任务。');});}
function retest(){if(!manager())return;const r=data().defects.find(r=>r.id===drawerId);modal('登记独立复测',`<div class="notice">目标修复版本：${esc(r.fixedVersion)}；用例：${esc(r.caseId)}。执行者声明与复测结论分别保留。</div><div class="section-gap">${field('version','实际复测版本','','text','必须与目标修复版本一致；原型示例使用 demo-fix-01。')}${field('environment','实际测试环境',r.environment)}${field('case','实际用例',r.caseId)}${fieldSelect('result','复测结果',['通过','失败','无法完成'],'通过')}${field('evidence','证据入口与结论','','textarea','生产实现需要固定原件引用与完整性信息，不保存到源码 Git。')}</div>`,form=>{if(form.get('version').trim()!==r.fixedVersion||form.get('case').trim()!==r.caseId)throw Error('实际版本或用例不匹配；不能用旧记录关闭当前缺陷。');if(form.get('result')==='通过'){r.status='已关闭';eventRow(r,'复测通过，关闭缺陷',form.get('evidence')+'\n版本 '+r.fixedVersion+'；环境 '+form.get('environment'));notify('演示缺陷已关闭，原修复与复测记录均保留。');}else{r.status=form.get('result')==='失败'?'重开':'待复测';eventRow(r,'复测'+form.get('result'),form.get('evidence'));notify('保留失败 / 未验证记录，不声明关闭。');}});}
function coverage(){modal('统计口径与采集范围',`<div class="notice">这里的数字全部是演示样本，不是当前真实账户或项目用量。</div><dl class="details-grid section-gap"><div><dt>统计时段</dt><dd>2026-11-10 至 11-16<br>Asia/Shanghai</dd></div><div><dt>统计范围</dt><dd>当前项目已登记的 23 个会话；不代表整个账号全部会话</dd></div><div><dt>来源与完整度</dt><dd>13 完整 / 5 部分 / 5 未接入</dd></div><div><dt>归属</dt><dd>项目级调研与待归因单列，不分摊给任务</dd></div></dl><h3 class="section-gap">合计规则</h3><ul class="compact-list secondary"><li>合计 = 输入 + 输出。缓存与推理是细分项，不再加一次。</li><li>重复报告和导入以同源调用 ID 去重；流式样本由最终样本替代。</li><li>失败调用只计已报告的消耗；未报告部分标未知。</li><li>“导入已核对”说明来源经过核对，不证明供应商账单金额。</li><li>订阅额度、实际费用、上下文占用与历史累计用量分开。</li></ul><p class="small muted section-gap">完整设计包括计数器重置、晚到记录、跨阶段归因和字段映射。生产实现必须逐运行时验证。</p><div class="form-footer">${btn('阅读采集设计','design-section','data-section="tokens"','primary')}</div>`);}
function exportUsage(){const columns=['记录ID','日期','模型','运行时','任务','阶段','输入','输出','合计','来源','覆盖'];const csvCell=v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const lines=[columns,...usageRows().map(r=>[r.id,r.date,r.model,r.runtime,r.task,r.phase,r.input,r.output,r.input+r.output,r.quality,r.coverage])];const blob=new Blob(['\uFEFF'+lines.map(row=>row.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='DEMO-project-token-usage.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('导出当前筛选的演示明细；不包含凭据或真实会话。');}
function commandSearch(){modal('搜索当前项目',`<label class="sr-only" for="command-query">搜索当前项目</label><input type="search" class="search-command-input" id="command-query" placeholder="需求、缺陷、任务编号或标题"><div id="command-results" class="command-results"></div>`);const input=$('command-query'),draw=()=>{const q=input.value.toLowerCase();let found=[];for(const [kind,key] of [['requirement','requirements'],['defect','defects'],['task','tasks']])found.push(...data()[key].filter(r=>[r.id,r.title].join(' ').toLowerCase().includes(q)).map(r=>({kind,...r})));$('command-results').innerHTML=found.slice(0,12).map(r=>btn(`<span>${esc(r.title)}</span><span class="small muted">${r.id}</span>`,'command-result',`data-kind="${r.kind}" data-id="${r.id}"`)).join('')||'<p class="muted">当前项目没有匹配对象。</p>';};input.oninput=draw;draw();input.focus();}
function closeNav(){$('sidebar').classList.remove('open');$('nav-scrim').hidden=true;$('menu-toggle').setAttribute('aria-expanded','false');}
document.addEventListener('click',event=>{
 const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;
 if(action==='route')return openRoute(b.dataset.route);
 if(action==='open'){if($('modal').open)$('modal').close();return openDrawer(b.dataset.kind,b.dataset.id,b.dataset.tab||'概述');}
 if(action==='close-drawer')return closeDrawer();
 if(action==='drawer-tab')return openDrawer(drawerKind,drawerId,b.dataset.value);
 if(action==='close-modal')return $('modal').close();
 if(action==='design-section'){const a=document.createElement('a');a.href='guide.html#'+(b.dataset.section||'summary');a.target='_blank';a.rel='noopener';a.click();return;}
 if(action==='create-requirement')return createRequirement();if(action==='create-defect')return createDefect();if(action==='refine')return refineRequirement();if(action==='link-task')return linkTask();if(action==='propose-change')return proposeChange();if(action==='retest')return retest();if(action==='review-change')return reviewChange();if(action==='coverage')return coverage();if(action==='export-usage')return exportUsage();
 if(action==='req-view'){f().view=b.dataset.value;f().page=1;selected.clear();return render();}
 if(action==='time-view'){f().view=b.dataset.value;return render();}
 if(action==='sort'){f().dir=f().sort===b.dataset.key?-f().dir:1;f().sort=b.dataset.key;return render();}
 if(action==='clear-filters'){Object.assign(f(),{query:'',status:'全部',priority:'全部',type:'全部',view:'全部',page:1});selected.clear();return render();}
 if(action==='page-next'||action==='page-prev'){f().page+=action==='page-next'?1:-1;selected.clear();return render();}
 if(action==='toggle-view'){f().mode=f().mode==='board'?'list':'board';return render();}
 if(action==='columns'){modal('列与信息密度',`<p class="small muted">必要字段始终可见；移动端优先保留编号、标题与状态。</p><label class="checkline"><input id="dense-setting" type="checkbox" ${state.dense?'checked':''}>使用紧凑行距（桌面）</label><label class="checkline"><input type="checkbox" checked disabled>标题与状态</label><label class="checkline"><input type="checkbox" checked disabled>任务关联</label><p class="small muted section-gap">本原型演示密度切换；完整自定义列与可保存视图在设计规格中定义。</p>`);$('dense-setting').onchange=e=>{state.dense=e.target.checked;persist();document.body.classList.toggle('dense',state.dense);};return;}
 if(action==='saved-views'){modal('当前项目的已保存视图',`<div class="command-results">${btn('全部需求','apply-saved','data-value="全部"')}${btn('待澄清与待评估','apply-saved','data-value="待澄清"')}${btn('未工程化想法','apply-saved','data-value="想法池"')}</div><p class="small muted section-gap">保存范围按用户与项目隔离，不会带到其他项目。</p>`);return;}
 if(action==='apply-saved'){Object.assign(f(),{view:b.dataset.value,query:'',status:'全部',type:'全部',page:1});$('modal').close();render();return;}
 if(action==='choose-change'){const rows=data().requirements.filter(r=>r.version);modal('选择需要调整的有效需求',`<div class="command-results">${rows.map(r=>btn(esc(r.id+' · '+r.title),'change-target',`data-id="${r.id}"`)).join('')||'<p class="muted">当前没有已定版需求。</p>'}</div>`);return;}
 if(action==='change-target'){return proposeChange(b.dataset.id);}
 if(action==='clear-selection'){selected.clear();return render();}
 if(action==='bulk-tag'&&manager()){const ids=[...selected];modal('批量设置标签',`<p class="small muted">选中 ${ids.length} 个需求。这里只修改标签，不批量批准范围或工程化。</p>${field('tag','标签','本轮关注')}`,form=>{for(const r of data().requirements.filter(r=>ids.includes(r.id))){const tag=form.get('tag').trim();if(tag&&!r.tags.includes(tag))r.tags.push(tag);}selected.clear();notify('标签已更新；承诺和验收状态保持。');});return;}
 if(action==='comment'){const body=$('comment-text').value.trim();if(!body)return notify('请填写评论内容。');const item=drawerKind==='requirement'?data().requirements.find(r=>r.id===drawerId):data().defects.find(r=>r.id===drawerId);item.comments.push({who:state.role==='worker'?'Worker':state.role==='human'?'人类所有者':'项目 SE',at:'11-16 · 原型操作',body});persist();openDrawer(drawerKind,drawerId,'讨论');return;}
 if(action==='validate-requirement'&&manager()){const r=data().requirements.find(r=>r.id===drawerId);modal('确认业务目标达成',`<div class="notice">任务已完成不代表目标自动达成。请核对所有标准与对应验证。</div><div class="section-gap">${r.criteria.map(c=>`<div class="criterion">${badge(c.passed?'已验证':'待验证')} ${esc(c.id+' · '+c.text)}<p class="small">${esc(c.evidence)}</p></div>`).join('')}</div>${field('reason','目标达成核对结论','','textarea')}`,form=>{if(!r.criteria.length||r.criteria.some(c=>!c.passed))throw Error('仍有未验证标准，不能确认需求达成。');r.status='已达成';eventRow(r,'确认业务目标达成',form.get('reason'));notify('需求达成结论已记录，原任务和验证历史保留。');});return;}
 if(action==='reopen-defect'&&manager()){const r=data().defects.find(r=>r.id===drawerId);modal('重新打开缺陷',field('reason','新的复现现象与版本','','textarea'),form=>{r.status='重开';eventRow(r,'重新打开缺陷',form.get('reason'));notify('已重开并保留之前的复测结论。');});return;}
 if(action==='available-tasks'){f().query='待领取';notify('当前可领取示例：PB-T-103、PB-T-107。草案任务尚未发布。');modal('当前可领取任务',data().tasks.filter(t=>t.status==='待领取').map(t=>taskLink(t.id)).join('')||'<p class="muted">当前没有可领取任务。</p>');return;}
 if(action==='command-result'){$('modal').close();openDrawer(b.dataset.kind,b.dataset.id);return;}
 if(action==='usage-group'){const label=b.dataset.value;modal('用量分组 · '+label,`<p class="small muted">当前筛选下的演示记录；分组不是额外的用量副本。</p><div class="stack-list">${usageRows().filter(r=>r.phase===label||r.model===label||r.task===label||(label==='项目级调研'&&!r.task&&r.phase!=='未归因')||(label==='待归因'&&r.phase==='未归因')).map(r=>`<div class="stack-row"><div><h4>${esc(r.model)} · ${short(r.input+r.output)}</h4><p>${r.date} · ${r.quality} · ${r.task||r.phase}</p></div></div>`).join('')||'<p class="prose section-gap">此处为时间分析示意，实际优化需结合等待原因与任务记录。</p>'}</div>`);}
});
document.addEventListener('change',event=>{const node=event.target;if(node.dataset.check){if(node.checked)selected.add(node.dataset.check);else selected.delete(node.dataset.check);$('bulk-bar').hidden=!selected.size;$('bulk-count').textContent='已选 '+selected.size;}if(node.id==='select-visible'){document.querySelectorAll('[data-check]').forEach(c=>{c.checked=node.checked;if(node.checked)selected.add(c.dataset.check);else selected.delete(c.dataset.check);});$('bulk-bar').hidden=!selected.size;$('bulk-count').textContent='已选 '+selected.size;}});
$('project').onchange=e=>{closeDrawer(false);state.project=e.target.value;selected.clear();$('modal').close();render();notify('已切换项目，详情与选择已清空；只显示当前项目数据。');};
$('role').onchange=e=>{closeDrawer(false);state.role=e.target.value;selected.clear();render();notify('已切换演示身份；真实权限由生产服务端判断。');};
$('theme-toggle').onclick=()=>{state.theme=state.theme==='light'?'dark':'light';render();};
$('menu-toggle').onclick=()=>{const open=$('sidebar').classList.toggle('open');$('nav-scrim').hidden=!open;$('menu-toggle').setAttribute('aria-expanded',String(open));};$('nav-scrim').onclick=closeNav;
$('drawer-backdrop').onclick=()=>closeDrawer();$('modal-close').onclick=()=>$('modal').close();$('command-open').onclick=commandSearch;
$('reset-demo').onclick=()=>modal('重置本原型的数据',`<p class="prose">只清除这个原型在当前浏览器保存的演示数据，不会访问或修改公告板、NAS 或其他网站的数据。</p><div class="form-footer">${btn('取消','close-modal')}${btn('重置演示','confirm-reset','','primary')}</div>`);
document.addEventListener('click',e=>{if(e.target.closest('[data-action="confirm-reset"]')){state=fresh();route='requirements';location.hash=route;selected.clear();$('modal').close();closeDrawer(false);closeNav();render();notify('已恢复演示初始数据。');}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('drawer').hidden)return;commandSearch();}if(e.key==='Escape'&&!$('modal').open){if(!$('drawer').hidden){e.preventDefault();closeDrawer();}closeNav();}if(e.key==='Tab'&&!$('drawer').hidden&&!$('modal').open){const focusable=[...$('drawer').querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select,textarea')].filter(n=>n.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('drawer'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===$('drawer'))){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{const parts=location.hash.slice(1).split('/'),next=routes[parts[0]]?parts[0]:'requirements';if(next!==route){closeDrawer(false);route=next;selected.clear();render();}if(parts.length>=3)openDrawer(parts[1],decodeURIComponent(parts.slice(2).join('/')));else if(drawerId)closeDrawer(false);});
render();const initial=location.hash.slice(1).split('/');if(initial.length>=3)openDrawer(initial[1],decodeURIComponent(initial[2]));
